-- keep all interactions (prompts/messages) consistent in style!
-- all this code generated by ChatGPT for styling
local UI = {}

UI.padding = 16
UI.rounding = 12
UI.fontSize = 16
UI.borderWidth = 2

UI.background = {0.05, 0.07, 0.10, 0.90}
UI.border = {0.40, 0.48, 0.54, 1}
UI.textColor = {1, 1, 1, 1}
UI.titleColor = {0.95, 0.83, 0.55, 1}

function UI.init()
    UI.font = love.graphics.newFont(UI.fontSize)
end

-- draw rounded rectangle using shared colors
function UI.drawBox(x, y, w, h)
    love.graphics.setColor(UI.background)
    love.graphics.rectangle(
        "fill", x, y, w, h,
        UI.rounding, UI.rounding
    )

    love.graphics.setColor(UI.border)
    love.graphics.setLineWidth(UI.borderWidth)
    love.graphics.rectangle(
        "line", x, y, w, h,
        UI.rounding, UI.rounding
    )

    love.graphics.setColor(1, 1, 1, 1)
end

-- draw message near bottom of screen
function UI.drawMessage(message)
    if not message then
        return
    end

    local screenW, screenH = love.graphics.getDimensions()

    local margin = 12
    local boxW = screenW - margin * 2

    love.graphics.push("all")
    love.graphics.origin()
    love.graphics.setFont(UI.font)

    local textW = boxW - UI.padding * 2
    local _, lines = UI.font:getWrap(message, textW)

    local lineH = UI.font:getHeight() * 1.2
    local boxH = math.max(
        105,
        #lines * lineH + UI.padding * 2
    )

    local boxX = margin
    local boxY = screenH - boxH - margin

    UI.drawBox(boxX, boxY, boxW, boxH)

    love.graphics.setColor(UI.textColor)
    love.graphics.printf(
        message,
        boxX + UI.padding,
        boxY + UI.padding,
        textW,
        "left"
    )

    love.graphics.pop()
end

-- draw E prompt centered over interactable
function UI.drawPrompt(message, object)
    local font = UI.font
    local padding = 10

    local boxW = font:getWidth(message) + padding * 2
    local boxH = font:getHeight() + padding * 2

    local centerX = object.x + (object.width or 0) / 2
    local boxX = centerX - boxW / 2
    local boxY = object.y - boxH - 4

    love.graphics.push("all")
    love.graphics.setFont(font)

    UI.drawBox(boxX, boxY, boxW, boxH)

    love.graphics.setColor(UI.textColor)
    love.graphics.print(
        message,
        boxX + padding,
        boxY + padding
    )

    love.graphics.pop()
end

return UI